import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"54 - Scalping Terminal And Risk Monitor","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/54-scalping-terminal.md","filePath":"developers/design-documentation/54-scalping-terminal.md"}'),s={name:"developers/design-documentation/54-scalping-terminal.md"};function r(n,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_54-scalping-terminal-and-risk-monitor" tabindex="-1">54 - Scalping Terminal And Risk Monitor <a class="header-anchor" href="#_54-scalping-terminal-and-risk-monitor" aria-label="Permalink to &quot;54 - Scalping Terminal And Risk Monitor&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><code>/scalping</code> is a session-authenticated trading workspace for fast equity, futures, and options execution. It combines contract discovery, order/position views, WebSocket ticks, optional live charts, tracked legs, and persisted server-side stop/target/trailing-stop management.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>blueprints/scalping.py</code></td><td>Session APIs for discovery, history, execution, exits, tracked legs, stops</td></tr><tr><td><code>database/scalping_db.py</code></td><td>Mode-separated stop state and tracked symbols</td></tr><tr><td><code>services/scalping_risk_monitor_service.py</code></td><td>Long-lived tick evaluation and reducing exits</td></tr><tr><td><code>frontend/src/pages/Scalping.tsx</code></td><td>Terminal interaction and state composition</td></tr><tr><td><code>frontend/src/api/scalping.ts</code></td><td>Typed blueprint client</td></tr><tr><td><code>frontend/src/components/scalping/ScalpChart.tsx</code></td><td>Candles and volume</td></tr><tr><td><code>frontend/src/components/scalping/SetSLDialog.tsx</code></td><td>Stop/target/trailing configuration</td></tr></tbody></table><h2 id="session-apis" tabindex="-1">Session APIs <a class="header-anchor" href="#session-apis" aria-label="Permalink to &quot;Session APIs&quot;">​</a></h2><p>The blueprint provides underlyings, all-underlying search, expiry, strikes, futures, symbol search, history, order, close-leg, close-all, cancel-all, tracked-symbol GET/DELETE, and stop GET/POST/DELETE resources under <code>/scalping/api</code>.</p><p>These are browser session APIs, not public <code>/api/v1</code> API-key endpoints. They resolve the current user&#39;s Tradeboard API key internally.</p><h2 id="instruments-and-execution" tabindex="-1">Instruments And Execution <a class="header-anchor" href="#instruments-and-execution" aria-label="Permalink to &quot;Instruments And Execution&quot;">​</a></h2><p>Supported execution exchanges are <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>MCX</code>, and <code>CDS</code>. Derivatives allow <code>MIS</code>/<code>NRML</code>; equities allow <code>MIS</code>/<code>CNC</code>. Index underlyings map to their quote and F&amp;O exchanges, while MCX/CDS option chains can use the current-month future as reference.</p><p>Server-side safety rails include:</p><ul><li><code>BUY</code> or <code>SELL</code> only.</li><li>Maximum 20 lots per manual request.</li><li>Absolute maximum 100,000 units.</li><li>Derivative quantity must respect the contract lot size.</li><li>Exit routes derive the opposite action from the actual position and cannot increase exposure.</li><li>Order strategy is stamped as <code>Scalping</code>.</li></ul><p>Analyzer/live mode is read from the global application setting and used to segregate tracking and stop rows.</p><h2 id="market-data-and-books" tabindex="-1">Market Data And Books <a class="header-anchor" href="#market-data-and-books" aria-label="Permalink to &quot;Market Data And Books&quot;">​</a></h2><p>The page uses the shared browser market-data manager for ticks and Socket.IO order events for throttled order/trade/position refresh. Stale ticks can fall back to multi-quotes. Client filtering keeps displayed book entries scoped to the current day when timestamps are parseable.</p><p>History supports <code>1m</code>, <code>5m</code>, and <code>15m</code> with lookbacks of 1, 3, and 9 trading days. Returned chart times are shifted for Lightweight Charts&#39; UTC rendering so displayed bars align with IST. Indices can legitimately have zero volume.</p><p>Charts are off by default because three live charts create additional subscriptions and history reconciliation. The charts toggle and timeframe are stored in browser local storage.</p><h2 id="persisted-stops" tabindex="-1">Persisted Stops <a class="header-anchor" href="#persisted-stops" aria-label="Permalink to &quot;Persisted Stops&quot;">​</a></h2><p>A stop row is keyed by symbol, exchange, product, and mode. It stores side, quantity, entry/stop/target values, trailing settings, current trailed stop, and runtime state. POST validates finite/non-negative inputs and verifies that a reducing exit can be placed before persistence.</p><p>The browser configures and displays this state, but it is not the risk engine.</p><h2 id="server-risk-monitor" tabindex="-1">Server Risk Monitor <a class="header-anchor" href="#server-risk-monitor" aria-label="Permalink to &quot;Server Risk Monitor&quot;">​</a></h2><p>The singleton monitor starts with application environment setup and owns an internal WebSocket client. It synchronizes active rows, subscribes/unsubscribes symbols, evaluates each tick, persists trailed-stop advances with rate limiting, and submits whole-lot, freeze-safe reducing exits on stop or target breach.</p><p>This design keeps protection active when the browser navigates away or closes. The monitor rechecks live position state before execution as a backstop. <code>stop()</code> disconnects and is registered for process exit cleanup.</p><h2 id="failure-boundaries" tabindex="-1">Failure Boundaries <a class="header-anchor" href="#failure-boundaries" aria-label="Permalink to &quot;Failure Boundaries&quot;">​</a></h2><ul><li>Saving/deleting stop state notifies the monitor but a notification hiccup does not fail the persistence request.</li><li>Feed unavailability is logged and retried through synchronization rather than corrupting stop state.</li><li>Invalid/string broker numerics are normalized before position calculations.</li><li>Broker history gaps do not stop live chart tick formation.</li><li>The monitor only reduces exposure; it is not a general strategy entry engine.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><code>test/test_scalping_risk_monitor.py</code> covers trailing-stop evaluation and monitor behavior. Frontend tests cover scalping price, row, tick, and trailing-stop helpers. Changes to execution rails require both server validation and UI regression coverage.</p>',27)])])}const m=t(s,[["render",r]]);export{h as __pageData,m as default};
